  "  ~ remember protect, ellis \"took the case because nobody else would\"",
  "  -> the_scan",
  "* Take it because a case this big makes a career",
  "  ~ motive = \"career\"",
  "  ~ remember ambition, career \"took the case because it would make your name\"",
  "  -> the_scan",
  "* Take it because it's your turn on the legal aid rota, and that's the job",
  "  ~ motive = \"rota\"",
  "  ~ remember rota, job \"took the case because it was your turn\"",
  "  -> the_scan",
